1	<?php
2	
3	namespace App\Services\Media;
4	
5	use App\Models\Core\MediaVariant;
6	use App\Models\Core\Site\SiteMedia;
7	use Illuminate\Support\Facades\Log;
8	use Illuminate\Support\Facades\Storage;
9	use Symfony\Component\Process\Process;
10	
11	/**
12	 * Transcodes a video original into MP4 + HLS variants and a poster image,
13	 * stores all artifacts on the media disk, and persists MediaVariant rows.
14	 *
15	 * Processing order (avoids extra re-encodes):
16	 *   1. FFprobe  – extract metadata + validate duration
17	 *   2. FFmpeg   – encode optimized MP4 (720p)
18	 *   3. FFmpeg   – encode maximized MP4 (1080p)
19	 *   4. FFmpeg   – package HLS segments from each MP4 (stream-copy, no re-encode)
20	 *   5. Build    – write master adaptive HLS playlist
21	 *   6. FFmpeg   – extract poster JPEG at 1s mark
22	 *   7. Upload   – stream all artifacts to media disk
23	 *   8. DB upsert – persist one MediaVariant row per logical artifact
24	 *   9. SiteMedia update – set processing_state, duration_ms, poster_path
25	 *
26	 * Storage layout under the media disk:
27	 *   videos/{proId}/{mediaId}/
28	 *     original_{hash}.{ext}
29	 *     optimized.mp4
30	 *     maximized.mp4
31	 *     hls/
32	 *       optimized/playlist.m3u8  + seg_*.ts
33	 *       maximized/playlist.m3u8  + seg_*.ts
34	 *       adaptive.m3u8             (master playlist)
35	 *     poster.jpg
36	 *
37	 * Requires ffmpeg and ffprobe to be available (configured via config/sidest.php).
38	 */
39	// V2: Transcodes videos to MP4 + HLS via FFmpeg. Feature-flagged (SIDEST_VIDEO_UPLOADS_ENABLED). Uses dedicated redis_video connection.
40	class VideoVariantService
41	{
42	    /* ------------------------------------------------------------------ */
43	    /*  Public API */
44	    /* ------------------------------------------------------------------ */
45	
46	    /**
47	     * Run FFprobe on a local file and return metadata array.
48	     * Throws \RuntimeException if the binary fails.
49	     *
50	     * @return array<string, mixed>
51	     */
52	    public function probe(string $localPath): array
53	    {
54	        $ffprobe = $this->ffprobeBinary();
55	        $cmd = sprintf(
56	            '%s -v quiet -print_format json -show_format -show_streams %s 2>&1',
57	            escapeshellcmd($ffprobe),
58	            escapeshellarg($localPath),
59	        );
60	
61	        $output = $this->runCommand($cmd, $exitCode);
62	
63	        if ($exitCode !== 0) {
64	            throw new \RuntimeException("ffprobe failed (exit {$exitCode}): {$output}");
65	        }
66	
67	        $data = json_decode($output, true);
68	        if (! is_array($data)) {
69	            throw new \RuntimeException('ffprobe returned non-JSON output.');
70	        }
71	
72	        return $data;
73	    }
74	
75	    /**
76	     * Probe a local file and validate it contains at least one video stream
77	     * and does not exceed the configured maximum duration.
78	     *
79	     * Call this in the upload controller before storing to R2 so malformed
80	     * containers and over-length videos are rejected at the HTTP boundary,
81	     * not on the worker.
82	     *
83	     * @return array<string, mixed> Raw ffprobe data (reuse to avoid a second probe).
84	     * @throws \RuntimeException if the container is unreadable, has no video stream, or exceeds max duration.
85	     */
86	    public function probeAndValidate(string $localPath): array
87	    {
88	        $probe = $this->probe($localPath);
89	
90	        $hasVideoStream = false;
91	        foreach ($probe['streams'] ?? [] as $stream) {
92	            if (($stream['codec_type'] ?? '') === 'video') {
93	                $hasVideoStream = true;
94	                break;
95	            }
96	        }
97	
98	        if (! $hasVideoStream) {
99	            throw new \RuntimeException('File does not contain a recognisable video stream.');
100	        }
101	
102	        $durationMs = $this->extractDurationMs($probe);
103	        $maxDurSec = (int) config('sidest.video_max_duration_seconds', 300);
104	
105	        if ($durationMs > $maxDurSec * 1000) {
106	            $actualSec = (int) round($durationMs / 1000);
107	            throw new \RuntimeException(
108	                "Video is too long ({$actualSec}s). Maximum allowed duration is {$maxDurSec}s."
109	            );
110	        }
111	
112	        return $probe;
113	    }
114	
115	    /**
116	     * Process a video original into all configured artifacts.
117	     *
118	     * @throws \RuntimeException on unrecoverable processing errors
119	     */
120	    public function processVariants(
121	        string $localOriginalPath,
122	        string $mediaId,
123	        string $basePath,
124	    ): void {
125	        Log::info('VideoVariantService: starting', [
126	            'media_id' => $mediaId,
127	            'base_path' => $basePath,
128	        ]);
129	
130	        // --- 1. Probe metadata ---
131	        $probe = $this->probe($localOriginalPath);
132	        $durationMs = $this->extractDurationMs($probe);
133	        $maxDur = (int) config('sidest.video_max_duration_seconds', 300);
134	
135	        if ($durationMs > $maxDur * 1000) {
136	            throw new \RuntimeException(
137	                "Video duration ({$durationMs}ms) exceeds maximum ({$maxDur}s)."
138	            );
139	        }
140	
141	        $variantDefs = (array) config('sidest.video_variants', []);
142	        $tmpDirs = [];
143	
144	        try {
145	            // --- 2 & 3. Encode MP4 variants ---
146	            $mp4Paths = [];
147	            foreach ($variantDefs as $variantKey => $def) {
148	                $tmpMp4 = $this->makeTmpFile("sidest_mp4_{$variantKey}_", '.mp4');
149	                $this->encodeMp4($localOriginalPath, $tmpMp4, $def);
150	                $mp4Paths[$variantKey] = $tmpMp4;
151	            }
152	
153	            // --- 4. Package HLS from each MP4 ---
154	            $hlsDirs = [];
155	            foreach ($mp4Paths as $variantKey => $mp4) {
156	                $tmpHlsDir = sys_get_temp_dir().'/sidest_hls_'.$variantKey.'_'.uniqid();
157	                if (! mkdir($tmpHlsDir, 0755, true)) {
158	                    throw new \RuntimeException("Failed to create HLS temp dir: {$tmpHlsDir}");
159	                }
160	                $tmpDirs[] = $tmpHlsDir;
161	                $this->packageHls($mp4, $tmpHlsDir.'/playlist.m3u8');
162	                $hlsDirs[$variantKey] = $tmpHlsDir;
163	            }
164	
165	            // --- 5. Build adaptive master playlist ---
166	            $adaptiveContent = $this->buildAdaptivePlaylist($variantDefs);
167	
168	            // --- 6. Extract poster ---
169	            $tmpPoster = $this->makeTmpFile('sidest_poster_', '.jpg');
170	            $this->extractPoster($localOriginalPath, $tmpPoster);
171	
172	            // --- 7. Upload all artifacts ---
173	            $disk = $this->disk();
174	            $diskName = $this->resolvedDiskName();
175	
176	            // Upload MP4s
177	            foreach ($mp4Paths as $variantKey => $mp4) {
178	                $remotePath = "{$basePath}/{$variantKey}.mp4";
179	                $stream = fopen($mp4, 'rb');
180	                $disk->put($remotePath, $stream, 'public');
181	                if (is_resource($stream)) {
182	                    fclose($stream);
183	                }
184	
185	                $def = $variantDefs[$variantKey] ?? [];
186	                // Unique key: (media_id, variant_key, artifact_type)
187	                MediaVariant::updateOrCreate(
188	                    ['media_id' => $mediaId, 'variant_key' => $variantKey, 'artifact_type' => 'mp4'],
189	                    [
190	                        'disk' => $diskName,
191	                        'path' => $remotePath,
192	                        'mime' => 'video/mp4',
193	                        'bitrate_kbps' => (int) ($def['video_bitrate_kbps'] ?? 0) + (int) ($def['audio_bitrate_kbps'] ?? 0),
194	                        'file_size_bytes' => filesize($mp4) ?: null,
195	                        'duration_ms' => $durationMs,
196	                        'metadata' => ['resolution' => $def['resolution'] ?? null],
197	                    ]
198	                );
199	            }
200	
201	            // Upload HLS segments + playlists
202	            foreach ($hlsDirs as $variantKey => $hlsDir) {
203	                $remoteHlsBase = "{$basePath}/hls/{$variantKey}";
204	                foreach (scandir($hlsDir) ?: [] as $file) {
205	                    if ($file === '.' || $file === '..') {
206	                        continue;
207	                    }
208	                    $localFile = "{$hlsDir}/{$file}";
209	                    $remotePath = "{$remoteHlsBase}/{$file}";
210	                    $mime = str_ends_with($file, '.m3u8') ? 'application/vnd.apple.mpegurl' : 'video/mp2t';
211	                    $stream = fopen($localFile, 'rb');
212	                    $disk->put($remotePath, $stream, ['visibility' => 'public', 'ContentType' => $mime]);
213	                    if (is_resource($stream)) {
214	                        fclose($stream);
215	                    }
216	                }
217	
218	                $playlistPath = "{$remoteHlsBase}/playlist.m3u8";
219	                $def = $variantDefs[$variantKey] ?? [];
220	                MediaVariant::updateOrCreate(
221	                    ['media_id' => $mediaId, 'variant_key' => $variantKey, 'artifact_type' => 'hls_playlist'],
222	                    [
223	                        'disk' => $diskName,
224	                        'path' => $playlistPath,
225	                        'mime' => 'application/vnd.apple.mpegurl',
226	                        'duration_ms' => $durationMs,
227	                        'metadata' => ['resolution' => $def['resolution'] ?? null],
228	                    ]
229	                );
230	            }
231	
232	            // Upload adaptive master playlist
233	            $adaptiveRemotePath = "{$basePath}/hls/adaptive.m3u8";
234	            $disk->put($adaptiveRemotePath, $adaptiveContent, [
235	                'visibility' => 'public',
236	                'ContentType' => 'application/vnd.apple.mpegurl',
237	            ]);
238	
239	            MediaVariant::updateOrCreate(
240	                ['media_id' => $mediaId, 'variant_key' => 'adaptive', 'artifact_type' => 'hls_playlist'],
241	                [
242	                    'disk' => $diskName,
243	                    'path' => $adaptiveRemotePath,
244	                    'mime' => 'application/vnd.apple.mpegurl',
245	                ]
246	            );
247	
248	            // Upload poster
249	            $posterRemotePath = "{$basePath}/poster.jpg";
250	            $stream = fopen($tmpPoster, 'rb');
251	            $disk->put($posterRemotePath, $stream, ['visibility' => 'public', 'ContentType' => 'image/jpeg']);
252	            if (is_resource($stream)) {
253	                fclose($stream);
254	            }
255	
256	            MediaVariant::updateOrCreate(
257	                ['media_id' => $mediaId, 'variant_key' => 'poster', 'artifact_type' => 'poster'],
258	                [
259	                    'disk' => $diskName,
260	                    'path' => $posterRemotePath,
261	                    'mime' => 'image/jpeg',
262	                    'file_size_bytes' => filesize($tmpPoster) ?: null,
263	                ]
264	            );
265	
266	            // --- 8. Update SiteMedia ---
267	            SiteMedia::query()
268	                ->where('id', $mediaId)
269	                ->whereNull('deleted_at')
270	                ->update([
271	                    'processing_state' => SiteMedia::PROCESSING_STATE_READY,
272	                    'processing_error' => null,
273	                    'duration_ms' => $durationMs,
274	                    'poster_path' => $posterRemotePath,
275	                ]);
276	
277	            Log::info('VideoVariantService: completed', [
278	                'media_id' => $mediaId,
279	                'duration_ms' => $durationMs,
280	            ]);
281	        } finally {
282	            // Cleanup temp files and dirs
283	            foreach ($mp4Paths ?? [] as $mp4) {
284	                if (file_exists($mp4)) {
285	                    @unlink($mp4);
286	                }
287	            }
288	            if (isset($tmpPoster) && file_exists($tmpPoster)) {
289	                @unlink($tmpPoster);
290	            }
291	            foreach ($tmpDirs as $dir) {
292	                $this->removeDir($dir);
293	            }
294	        }
295	    }
296	
297	    /**
298	     * Delete all media_variants DB rows and all files under $basePath on disk.
299	     * Called by DeleteMediaArtifactsJob (async) for video cleanup.
300	     */
301	    public function deleteVariants(string $mediaId, string $basePath): void
302	    {
303	        $disk = $this->disk();
304	        $basePrefix = $this->normalizeVideoCleanupBasePath($basePath);
305	
306	        // Delete all files under the normalized video prefix.
307	        try {
308	            $files = $disk->allFiles($basePrefix);
309	        } catch (\Throwable $e) {
310	            throw new \RuntimeException(
311	                "Failed to list video artifacts for cleanup at [{$basePrefix}].",
312	                0,
313	                $e
314	            );
315	        }
316	
317	        foreach ($files as $file) {
318	            try {
319	                $deleted = $disk->delete($file);
320	            } catch (\Throwable $e) {
321	                throw new \RuntimeException(
322	                    "Failed to delete video artifact [{$file}].",
323	                    0,
324	                    $e
325	                );
326	            }
