439	     * Build the adaptive (master) HLS playlist content.
440	     *
441	     * @param  array<string, array<string, mixed>>  $variantDefs
442	     */
443	    private function buildAdaptivePlaylist(array $variantDefs): string
444	    {
445	        $lines = ['#EXTM3U'];
446	
447	        foreach ($variantDefs as $variantKey => $def) {
448	            // Guard against config values containing newlines or special chars
449	            // that would corrupt the line-based M3U8 format.
450	            if (! preg_match('/^[a-zA-Z0-9_-]+$/', (string) $variantKey)) {
451	                throw new \RuntimeException("Invalid video variant key: {$variantKey}");
452	            }
453	
454	            $videoBitrate = (int) ($def['video_bitrate_kbps'] ?? 2000);
455	            $audioBitrate = (int) ($def['audio_bitrate_kbps'] ?? 128);
456	            $bandwidth = ($videoBitrate + $audioBitrate) * 1000;
457	            $resolution = strtoupper((string) ($def['resolution'] ?? '1280x720'));
458	
459	            // Resolution must be WxH (digits only) — e.g. 1280x720, 1920X1080.
460	            if (! preg_match('/^\d+X\d+$/', $resolution)) {
461	                throw new \RuntimeException("Invalid video resolution for variant '{$variantKey}': {$resolution}");
462	            }
463	
464	            $lines[] = "#EXT-X-STREAM-INF:BANDWIDTH={$bandwidth},RESOLUTION={$resolution}";
465	            $lines[] = "{$variantKey}/playlist.m3u8";
466	        }
467	
468	        return implode("\n", $lines)."\n";
469	    }
