471	    private function extractDurationMs(array $probe): int
472	    {
473	        $duration = $probe['format']['duration'] ?? null;
474	        if ($duration === null) {
475	            // Fall back to the first video stream
476	            foreach ($probe['streams'] ?? [] as $stream) {
477	                if (($stream['codec_type'] ?? '') === 'video' && isset($stream['duration'])) {
478	                    $duration = $stream['duration'];
479	                    break;
480	                }
481	            }
482	        }
483	
484	        return $duration !== null ? (int) round((float) $duration * 1000) : 0;
