501	    /**
502	     * Run a pre-escaped shell command via Symfony Process and return its output.
503	     * $exitCode is set by reference.
504	     *
505	     * All arguments in $cmd must be escaped by the caller via
506	     * escapeshellcmd()/escapeshellarg() before this method is called.
507	     * No timeout is applied — video encoding can be arbitrarily long.
508	     */
509	    private function runCommand(string $cmd, ?int &$exitCode = null): string
510	    {
511	        $process = Process::fromShellCommandline($cmd);
512	        $process->setTimeout(null);
513	        $process->run();
514	
515	        $exitCode = $process->getExitCode() ?? 0;
516	
517	        // Callers append 2>&1, so all output (including stderr) is in stdout
518	        return $process->getOutput();
