521	    private function removeDir(string $dir): void
522	    {
523	        if (! is_dir($dir)) {
524	            return;
525	        }
526	
527	        foreach (scandir($dir) ?: [] as $file) {
528	            if ($file === '.' || $file === '..') {
529	                continue;
530	            }
531	            $path = "{$dir}/{$file}";
532	            is_dir($path) ? $this->removeDir($path) : @unlink($path);
533	        }
534	
535	        @rmdir($dir);
536	    }
