539	     * Legacy jobs may pass the original file path instead of the media directory.
540	     * Normalize to the directory prefix expected by allFiles().
541	     */
542	    private function normalizeVideoCleanupBasePath(string $basePath): string
543	    {
544	        $normalized = trim($basePath);
545	        if ($normalized === '') {
546	            throw new \RuntimeException('Video cleanup base path cannot be empty.');
547	        }
548	
549	        $leaf = basename($normalized);
550	        if (str_contains($leaf, '.')) {
551	            $normalized = dirname($normalized);
552	        }
553	
554	        $normalized = trim($normalized, '/');
555	        if ($normalized === '' || $normalized === '.') {
556	            throw new \RuntimeException('Video cleanup base path resolved to an invalid directory.');
557	        }
558	
559	        return $normalized;
560	    }
