562	    private function diskName(): string
563	    {
564	        $configured = (string) config('sidest.media_disk', 'media');
565	
566	        // $_ENV/$_SERVER are intentional here — Laravel Cloud caches config at deploy time
567	        // but injects platform env vars directly into the process environment at runtime,
568	        // so env()/config() won't see them. Direct superglobal access bypasses that cache.
569	        $explicit = $_ENV['SIDEST_MEDIA_DISK'] ?? $_SERVER['SIDEST_MEDIA_DISK'] ?? null;
570	        if (is_string($explicit) && trim($explicit) !== '') {
571	            return $configured;
572	        }
573	
574	        if ($configured === 'media') {
575	            $default = (string) config('filesystems.default', 'local');
576	            $defaultConfig = config("filesystems.disks.{$default}");
577	
578	            if (
579	                $default !== '' &&
580	                $default !== 'local' &&
581	                $default !== 'media' &&
582	                is_array($defaultConfig) &&
583	                (($defaultConfig['driver'] ?? null) === 's3')
584	            ) {
585	                return $default;
586	            }
587	        }
588	
589	        return $configured;
590	    }
